import{_ as r,a0 as a,w as s,s as u,ao as p,I as t,x as i,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"2016：如何選擇 Linux 桌面環境 | LCTT x X-CMD","titleTemplate":false,"description":"2016：如何選擇 Linux 桌面環境 | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2016：如何選擇 Linux 桌面環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2016：如何選擇 Linux 桌面環境 | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20160218 Best Linux Desktop Environments for 2016","title":"2016：如何選擇 Linux 桌面環境","tag":"201603","desc":""},"relativePath":"201603/20160218 Best Linux Desktop Environments for 2016.md","filePath":"[post].md"}'),m={name:"201603/20160218 Best Linux Desktop Environments for 2016.md"};function d(f,n,x,E,M,w){const l=a("Link");return s(),u("div",null,[n[39]||(n[39]=p('<h1 id="_2016-如何選擇-linux-桌面環境" tabindex="-1">2016：如何選擇 Linux 桌面環境 <a class="header-anchor" href="#_2016-如何選擇-linux-桌面環境" aria-label="Permalink to “2016：如何選擇 Linux 桌面環境”">​</a></h1><p><img src="http://www.linux.com/images/stories/66866/DE-2.png" alt=""></p><p>Linux 創建了一個友好的環境，為我們提供了選擇的可能。比方説，現代大多數的 Linux 發行版都提供不同桌面環境給我們來選擇。在本文中，我將挑選一些你可能會在 Linux 中見到的最棒的桌面環境來介紹。</p><h2 id="plasma" tabindex="-1">Plasma <a class="header-anchor" href="#plasma" aria-label="Permalink to “Plasma”">​</a></h2>',4)),t("p",null,[n[1]||(n[1]=i("我認為，",-1)),o(l,{href:"https://www.kde.org/workspaces/plasmadesktop/"},{default:e(()=>[...n[0]||(n[0]=[i("KDE 的 Plasma 桌面",-1)])]),_:1}),n[2]||(n[2]=i(" 是最先進的桌面環境 (LCTT 譯註：譯者認為，沒有什麼是最好的，只有最合適的，畢竟每個人的喜好都不可能完全相同)。它是我見過功能最完善和定製性最高的桌面環境；在用户完全自主控制方面，即使是 Mac OS X 和 Windows 也無法與之比擬。",-1))]),n[40]||(n[40]=t("p",null,"我愛 Plasma，因為它自帶了一個非常好的文件管理器 —— Dolphin。而相對應 Gnome 環境，我更喜歡 Plasma 的原因就在於這個文件管理器。使用 Gnome 最大的痛苦就是，它的文件管理器——Files——使我無法完成一些基本任務，比如説，批量文件重命名操作。而這個操作對我來説相當重要，因為我喜歡拍攝，但 Gnome 卻讓我無法批量重命名這些圖像文件。而使用 Dolphin 的話，這個操作就像在公園散步一樣簡單。",-1)),n[41]||(n[41]=t("p",null,"而且，你可以通過插件來增強 Plasma 的功能。Plasma 有大量的基礎軟件，如 Krita、Kdenlive、Calligra 辦公套件、digiKam、Kwrite 以及由 KDE 社區開發維護的大量應用。",-1)),n[42]||(n[42]=t("p",null,"Plasma 桌面環境唯一的缺陷就是它默認的郵件客户端——Kmail。它的設置比較困難，我希望 Kmail 設置可以配置地址簿和日曆。",-1)),n[43]||(n[43]=t("p",null,"包括 openSUSE 在內的多數主流發行版多使用 Plasma 作為默認桌面。",-1)),n[44]||(n[44]=t("h2",{id:"gnome",tabindex:"-1"},[i("GNOME "),t("a",{class:"header-anchor",href:"#gnome","aria-label":"Permalink to “GNOME”"},"​")],-1)),t("p",null,[o(l,{href:"https://www.gnome.org/"},{default:e(()=>[...n[3]||(n[3]=[i("GNOME",-1)])]),_:1}),n[5]||(n[5]=i(" (GNU Network Object Model Environment，GNU 網絡對象模型環境) 由 ",-1)),o(l,{href:"https://en.wikipedia.org/wiki/Miguel_de_Icaza"},{default:e(()=>[...n[4]||(n[4]=[i("Miguel de Icaza",-1)])]),_:1}),n[6]||(n[6]=i(" 和 Federico Mena 在 1997 年的時候創立，這是因為 KDE 使用了 Qt 工具包，而這個工具包是使用專屬許可證 (proprietary license) 發佈的。不像提供了大量定製的 KDE，GNOME 專注於讓事情變得簡單。因為其自身的簡單性和易用性，GNOME 變得相當流行。而我認為 GNOME 之所以流行的原因在於，Ubuntu——使用 GNOME 作為默認桌面的主流 Linux 發行版之一——對其有着巨大的推動作用。",-1))]),n[45]||(n[45]=t("p",null,"隨着時代變化，GNOME 也需要作出相應的改變了。因此，開發者在 GNOME 3 中推出了 GNOME 3 Shell，從而引出了它的全新設計規範。但這同時與 Canonical 的 Ubuntu 計劃存在者一些衝突，所以 Canonical 為 GNOME 開發了叫做 Unity 的自己的 Shell。最初，GNOME 3 Shell 因很多爭議 (issues) 而困擾不已——最明顯的是，升級之後會導致很多擴展無法正常工作。由於設計上的重大改版以及各種問題的出現，GNOME 便產生了很多分支（fork），比如 Cinnamon 和 Mate 桌面。",-1)),n[46]||(n[46]=t("p",null,"另外，使得 GNOME 讓人感興趣的是，它針對觸摸設備做了優化，所以，如果你有一台觸屏筆記本電腦的話，GNOME 則是最合適你這台電腦的桌面環境。",-1)),n[47]||(n[47]=t("p",null,"在 3.18 版本中，GNOME 已經作出了一些令人印象深刻的改動。其中他們所做的最讓人感興趣的是集成了 Google Drive，用户可以把他們的 Google Drive 掛載為遠程存儲設備，這樣就不必再使用瀏覽器來查看裏邊的文件了。我也很喜歡 GNOME 裏邊自帶的那個優秀的郵件客户端，它帶有日曆和地址簿功能。儘管有這麼多些優秀的特性，但它的文件管理器使我不再使用 GNOME ，因為我無法處理批量文件重命名。我會堅持使用 Plasma，一直到 GNOME 的開發者修復了這個小缺陷。",-1)),n[48]||(n[48]=t("p",null,[t("img",{src:"http://www.linux.com/images/stories/66866/DE-fig1.png",alt:""})],-1)),n[49]||(n[49]=t("h2",{id:"unity",tabindex:"-1"},[i("Unity "),t("a",{class:"header-anchor",href:"#unity","aria-label":"Permalink to “Unity”"},"​")],-1)),t("p",null,[n[8]||(n[8]=i("從技術上來説，",-1)),o(l,{href:"https://unity.ubuntu.com/"},{default:e(()=>[...n[7]||(n[7]=[i("Unity",-1)])]),_:1}),n[9]||(n[9]=i(" 並不是一個桌面環境，它只是 Canonical 為 Ubuntu 開發的一個圖形化 Shell。Unity 運行於 GNOME 桌面之上，並使用很多 GNOME 的應用和工具。Ubuntu 團隊分支了一些 GNOME 組件，以便更好的滿足 Unity 用户的需求。",-1))]),n[50]||(n[50]=t("p",null,"Unity 在 Ubuntu 的融合（convergence）計劃中扮演着重要角色， 在 Unity 8 中，Canonical 公司正在努力將電腦桌面和移動世界結合到一起。Canonical 同時還為 Unity 開發了許多的有趣技術，比如 HUD (Head-up Display，平視顯示)。他們還在 lenses 和 scopes 中通過一種獨特的技術來讓用户方便地找到特定內容。",-1)),n[51]||(n[51]=t("p",null,"即將發行的 Ubuntu 16.04，將會搭載 Unity 8，那時候用户就可以完全體驗開發者為該開源軟件添加的所有特性了。其中最大的爭議之一，Unity 可選取消集成了 Amazon Ads 和其他服務。而在即將發行的版本，Canonical 從 Dash 移除了 Amazon ads，但卻默認保證了系統的隱私性。",-1)),n[52]||(n[52]=t("h2",{id:"cinnamon",tabindex:"-1"},[i("Cinnamon "),t("a",{class:"header-anchor",href:"#cinnamon","aria-label":"Permalink to “Cinnamon”"},"​")],-1)),t("p",null,[n[12]||(n[12]=i("最初，[Cinnamon](",-1)),o(l,{href:"https://en.wikipedia.org/wiki/Cinnamon_(software%5C)"},{default:e(()=>[...n[10]||(n[10]=[i("https://en.wikipedia.org/wiki/Cinnamon_(software\\)",-1)])]),_:1}),n[13]||(n[13]=i(") 由 ",-1)),o(l,{href:"http://www.linuxmint.com/"},{default:e(()=>[...n[11]||(n[11]=[i("Linux Mint",-1)])]),_:1}),n[14]||(n[14]=i(" 開發 —— 這是 DistroWatch.com 上統計出來最流行的發行版。就像 Unity，Cinnamon 是 GNOME Shell 的一個分支。但最後進化為一個獨立的桌面環境，這是因為 Linux Mint 的開發者分支了 GNOME 桌面中很多的組件到 Cinnamon，包括 Files ——以滿足自身用户的需求。",-1))]),n[53]||(n[53]=t("p",null,"由於 Linux Mint 基於普通版本的 Ubuntu，開發者仍需要去完成 Ubuntu 尚未完成的目標。結果，儘管前途光明，但 Cinnamon 卻充滿了 Bugs 和問題。隨着 17.x 本版的發佈，Linux Mint 開始轉移到 Ubuntu 的 LTS 版本上，從而他們可以專注於開發 Cinnamon 的核心組件，而不必再去擔心代碼庫。轉移到 LTS 的好處是，Cinnamon 變得非常穩定並且基本沒有 Bugs 出現。現在，開發者已經開始向桌面環境中添加更多的新特性了。",-1)),n[54]||(n[54]=t("p",null,"對於那些更喜歡在 GNOME 基礎上有一個很好的類 Windows 用户界面的用户來説，Cinnamon 是他們最好的桌面環境。",-1)),n[55]||(n[55]=t("h2",{id:"mate-桌面",tabindex:"-1"},[i("MATE 桌面 "),t("a",{class:"header-anchor",href:"#mate-桌面","aria-label":"Permalink to “MATE 桌面”"},"​")],-1)),t("p",null,[o(l,{href:"http://mate-desktop.com/"},{default:e(()=>[...n[15]||(n[15]=[i("MATE 桌面",-1)])]),_:1}),n[16]||(n[16]=i(" 同樣是 GNOME 的一個分支，然而，它並不像 Cinnamon 那樣由 GNOME 3 分支而來，而是現在已經沒有人維護的 GNOME 2 代碼庫的一個分支。MATE 桌面中的一些開發者並不喜歡 GNOME 3 並且想要“繼續堅持” GNOME 2，所以他們使用這個代碼庫來創建來 MATE。為避免和 GNOME 3 的衝突，他們重命名了全部的包：Nautilus 改為 Caja、Gedit 改為 Pluma 以及 Evince 改為 Atril 等。",-1))]),n[56]||(n[56]=t("p",null,"儘管 MATE 延續了 GNOME 2，但這並不意味着他們使用過時的技術；相反，他們使用了更新的技術來提供一個現代的 GNOME 2 體驗。",-1)),n[57]||(n[57]=t("p",null,"擁有相當高的資源使用率才是 MATE 最令人印象深刻之處。你可將它運行在老舊硬件或者更新一些的但不太強大的硬件上，如樹梅派 (Raspberry Pi) 或者 Chromebook Flip。使得它更有讓人感興趣的是，把它運行在一些強大的硬件上，可以節省大多數的資源給其他應用，而桌面環境本身只佔用很少的資源。",-1)),n[58]||(n[58]=t("h2",{id:"lxqt",tabindex:"-1"},[i("LXQt "),t("a",{class:"header-anchor",href:"#lxqt","aria-label":"Permalink to “LXQt”"},"​")],-1)),t("p",null,[o(l,{href:"http://lxqt.org/"},{default:e(()=>[...n[17]||(n[17]=[i("LXQt",-1)])]),_:1}),n[18]||(n[18]=i(" 繼承了 LXDE ——最輕量級的桌面環境之一。它融合了 LXDE 和 Razor-Qt 兩個開源項目。LXQt 的首個可用本版（v 0.9）發佈於 2015 年。最初，開發者使用了 Qt4 ，之後為了加快開發速度，而放棄了兼容性，他們移動到 Qt5 和 KDE 框架上。我也在自己的 Arch 系統上嘗試使用了 LXQt，它的確是一個非常好的輕量級桌面環境。但在完全接過 LXDE 的傳承之前，LXQt 仍有一段很長的路需要走。",-1))]),n[59]||(n[59]=t("h2",{id:"xfce",tabindex:"-1"},[i("Xfce "),t("a",{class:"header-anchor",href:"#xfce","aria-label":"Permalink to “Xfce”"},"​")],-1)),t("p",null,[o(l,{href:"http://www.xfce.org/"},{default:e(()=>[...n[19]||(n[19]=[i("Xfce",-1)])]),_:1}),n[20]||(n[20]=i(" 早於 KDE 桌面環境，它是最古老和最輕量級的桌面環境。Xfce 的最新版本是 4.15，發佈於 2015 年，使用了諸如 GTK+ 3 的大量的現代科技。很多發行版都使用了 Xfce 環境以滿足特定需求，比如 Ubuntu Studio ——與 MATE 類似——儘量節省系統資源給其他的應用。並且，許多的著名的 Linux 發行版——包括 Manjaro Linux、PC/OS、Salix 和 Mythbuntu ——都把它作為默認桌面環境。",-1))]),n[60]||(n[60]=t("h2",{id:"budgie",tabindex:"-1"},[i("Budgie "),t("a",{class:"header-anchor",href:"#budgie","aria-label":"Permalink to “Budgie”"},"​")],-1)),t("p",null,[o(l,{href:"https://solus-project.com/budgie/"},{default:e(()=>[...n[21]||(n[21]=[i("Budgie",-1)])]),_:1}),n[22]||(n[22]=i(" 是一個新型的桌面環境，由 Solus Linux 團隊開發和維護。Solus 是一個從零開始構建的新型發行版，而 Budgie 則是它的一個核心組件。Budgie 使用了大量的 GNOME 組件，從而提供一個華麗的用户界面。由於沒有該桌面環境的更多信息，我特地聯繫了 Solus 的核心開發者—— Ikey Doherty。他解釋説：“我們搭載了自己的桌面環境—— Budgie 桌面。與其他桌面環境不同的是，Budgie 並不是其他桌面的一個分支，它的目標是徹底融入到 GNOME 協議棧之中。它完全從零開始編寫，並特意設計來迎合 Solus 提供的體驗。我們會盡可能的和 GNOME 的上游團隊協同工作，修復 Bugs，並提倡和支持他們的工作”。",-1))]),n[61]||(n[61]=t("h2",{id:"pantheon",tabindex:"-1"},[i("Pantheon "),t("a",{class:"header-anchor",href:"#pantheon","aria-label":"Permalink to “Pantheon”"},"​")],-1)),t("p",null,[n[24]||(n[24]=i("我想，",-1)),o(l,{href:"https://elementary.io/"},{default:e(()=>[...n[23]||(n[23]=[i("Pantheon",-1)])]),_:1}),n[25]||(n[25]=i(" 不需要特別介紹了吧，那個優美的 elementary OS 就使用它作為桌面。類似於 Budgie，很多人都認為 Pantheon 也不是 GNOME 的一個分支。elementary OS 團隊大多擁有良好的設計從業背景，所以他們會近距離關注每一個細節，這使得 Pantheon 成為一個非常優美的桌面環境。偶爾，它可能缺少像 Plasma 等桌面中的某些特性，但開發者實際上是盡其所能的去堅持設計原則。",-1))]),n[62]||(n[62]=t("p",null,[t("img",{src:"http://www.linux.com/images/stories/66866/DE-3.png",alt:""})],-1)),n[63]||(n[63]=t("h2",{id:"結論",tabindex:"-1"},[i("結論 "),t("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),n[64]||(n[64]=t("p",null,"當我寫完本文後，我突然意識到來開源和 Linux 的重大好處。總有一些東西適合你。就像 Jon “maddog” Hall 在最近的 SCaLE 14 上説的那樣：“是的，現在有 300 多個 Linux 發行版。我可以一個一個去嘗試，然後堅持使用我最喜歡的那一個”。",-1)),n[65]||(n[65]=t("p",null,"所以，盡情享受 Linux 的多樣性吧，最後使用最合你意的那一個。",-1)),n[66]||(n[66]=t("hr",null,null,-1)),t("p",null,[n[27]||(n[27]=i("via: ",-1)),o(l,{href:"http://www.linux.com/news/software/applications/881107-best-linux-desktop-environments-for-2016"},{default:e(()=>[...n[26]||(n[26]=[i("http://www.linux.com/news/software/applications/881107-best-linux-desktop-environments-for-2016",-1)])]),_:1})]),t("p",null,[n[31]||(n[31]=i("作者：",-1)),o(l,{href:"http://www.linux.com/community/forums/person/61003"},{default:e(()=>[...n[28]||(n[28]=[i("Swapnil Bhartiya",-1)])]),_:1}),n[32]||(n[32]=i(" 譯者：",-1)),o(l,{href:"https://github.com/GHLandy"},{default:e(()=>[...n[29]||(n[29]=[i("GHLandy",-1)])]),_:1}),n[33]||(n[33]=i(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:e(()=>[...n[30]||(n[30]=[i("wxy",-1)])]),_:1})]),t("p",null,[n[36]||(n[36]=i("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[34]||(n[34]=[i("LCTT",-1)])]),_:1}),n[37]||(n[37]=i(" 原創翻譯，",-1)),o(l,{href:"https://linux.cn/"},{default:e(()=>[...n[35]||(n[35]=[i("Linux中國",-1)])]),_:1}),n[38]||(n[38]=i(" 榮譽推出",-1))])])}const N=r(m,[["render",d]]);export{G as __pageData,N as default};
